/* DrawingOps demo · admin settings (S-14: F-42, F-43, F-38, F-40, F-13, F-54, F-39, I-01..I-13), automation
   (A-01..A-10), intelligence (G3, F-55..F-57), notification preferences (S-13: F-21) and profile. */
(function (root) {
  "use strict";
  const DO = root.DO; const { html, raw, icon, C } = DO; const st = DO.store; const ui = DO.ui;
  const S = DO.screens = DO.screens || {};
  const SECTIONS = [["organisation", "Organisation"], ["disciplines", "Disciplines"], ["stage-templates", "Stage templates"], ["codes", "Revision and purpose codes"], ["naming-rules", "Naming rules"], ["checklists", "Checklists"], ["intelligence", "Intelligence"], ["calendar", "Working calendar"], ["automation", "Automation"], ["users", "Users and roles"], ["contacts", "Contacts"], ["integrations", "Integrations"], ["onboarding", "Onboarding"], ["audit", "Audit trail"]];
  const audit = (what, text) => st.audit("settings", what, "edit", null, null, { text: `${DO.auth.current().name} ${text}` });
  const saved = (t) => ui.toast({ title: t || "Saved", description: "Changes apply to new records; existing records keep their values.", tone: "ok" });

  S.admin = (ctx, u) => {
    const caps = st.caps(u);
    const visible = SECTIONS.filter(([k]) => (k === "audit" ? caps.audit : caps.admin));
    const sec = ctx.params.section || (caps.admin ? "organisation" : "audit");
    if (sec === "contacts") { setTimeout(() => DO.app.go("/contacts"), 0); return html``; }
    if (!visible.some(([k]) => k === sec)) return C.card({ body: C.empty("This admin section needs the System admin role.") });
    const body = ({ organisation, disciplines, "stage-templates": templates, codes, "naming-rules": naming, checklists, intelligence, calendar, automation, users, integrations, onboarding, audit: auditTrail })[sec](u, ctx);
    return html`<div class="flex gap-6 wrap" style="align-items:flex-start"><nav aria-label="Admin sections" style="width:220px;flex:0 0 auto" class="hide-sm"><h1 class="title mb-2">Admin</h1><ul class="flex col gap-1">${visible.map(([k, l]) => html`<li><a href="#/admin/${k}" class="sidenav-like ${k === sec ? "active" : ""}" style="display:block;padding:6px 12px;border-radius:4px;${k === sec ? "background:var(--surface-muted);color:var(--primary);font-weight:600" : ""}">${l}</a></li>`)}</ul></nav>
      <div class="grow min-w-0"><div class="only-sm mb-3">${C.select({ options: visible, value: sec, change: "adm-nav", aria: "Admin section" })}</div>${body}</div></div>`;
  };
  ui.on("adm-nav", (el) => DO.app.go(`/admin/${el.value}`));
  const head = (title, meta, actions) => C.pageHead({ title, meta, actions });

  function organisation() {
    const o = st.S.org;
    return html`${head("Organisation", "Firm-wide defaults used by every project.")}<form data-submit="org-save" class="card"><div class="card-body form-grid">
      ${C.field("Firm name", html`<input id="o-n" name="name" class="input" value="${o.name}" required>`, { for: "o-n" })}${C.field("Tagline on title blocks", html`<input id="o-t" name="tagline" class="input" value="${o.tagline}">`, { for: "o-t" })}
      ${C.field("Address", html`<input id="o-a" name="address" class="input" value="${o.address}">`, { for: "o-a", cls: "full" })}
      ${C.field("Timezone", html`<input id="o-tz" class="input" value="${o.timezone}" disabled>`, { for: "o-tz", hint: "IST by default (N-08). Dates show as 23-Oct-2026; money with Indian grouping." })}${C.field("Project code format", html`<input id="o-c" name="code" class="input mono" value="${o.projectCodeFormat}">`, { for: "o-c" })}
      ${C.field("Default weekly capacity (hours)", html`<input id="o-cap" name="cap" type="number" class="input" value="${o.defaultCapacity}" min="10" max="60">`, { for: "o-cap", hint: "AS-08: 45 h; per-person capacity overrides it." })}${C.field("Daily digest time", html`<input id="o-dg" name="digest" type="time" class="input" value="${o.digestTime}">`, { for: "o-dg" })}
      ${C.field("Transmittal link valid for (days)", html`<input id="o-l" name="link" type="number" class="input" value="${o.linkDays}" min="1" max="365">`, { for: "o-l" })}${C.field("Flag unacknowledged transmittals after (days)", html`<input id="o-ack" name="ack" type="number" class="input" value="${o.ackDays}" min="1" max="60">`, { for: "o-ack" })}
    </div><div class="card-foot" style="justify-content:flex-end"><button class="btn primary">Save</button></div></form>`;
  }
  ui.on("org-save", (f, d) => { Object.assign(st.S.org, { name: d.name.trim() || st.S.org.name, tagline: d.tagline, address: d.address, projectCodeFormat: d.code, defaultCapacity: +d.cap, digestTime: d.digest, linkDays: +d.link, ackDays: +d.ack }); audit("organisation", "updated organisation settings"); st.commit(); saved(); });

  function disciplines() {
    return html`${head("Disciplines", "Each discipline has a sheet-number prefix rule used on create, import and upload (F-35).", C.btn("Add discipline", { variant: "primary", icon: "plus", act: "ds-add" }))}${C.card({ body: html`<div class="t-wrap"><table class="t"><thead><tr><th>Code</th><th>Name</th><th>Sheet-number rule (regex)</th><th>Test</th><th>Active</th></tr></thead><tbody>${st.S.disciplines.map((d, i) => html`<tr><td>${C.mono(d.code)}</td><td><input id="ds-n-${i}" class="input sm" value="${d.name}" data-change="ds-set" data-i="${i}" data-k="name" aria-label="Name for ${d.code}"></td><td><input id="ds-r-${i}" class="input sm mono" value="${d.regex}" data-change="ds-set" data-i="${i}" data-k="regex" aria-label="Rule for ${d.code}"></td><td><input class="input sm mono" style="width:110px" placeholder="${d.code}-101" data-input="ds-test" data-i="${i}" aria-label="Test a sheet number for ${d.code}"> <span id="ds-t-${i}" class="small"></span></td><td><label class="check"><input type="checkbox" ${d.active ? raw("checked") : ""} data-change="ds-set" data-i="${i}" data-k="active"><span class="sr-only">Active</span></label></td></tr>`)}</tbody></table></div>`, foot: `${st.S.sheets.length} sheets keep the numbers they were created with.` })}`;
  }
  ui.on("ds-set", (el) => { const d = st.S.disciplines[+el.dataset.i]; const k = el.dataset.k; const v = k === "active" ? el.checked : el.value; if (k === "regex") { try { new RegExp(v); } catch (e) { ui.toast({ title: "That is not a valid regular expression", description: e.message, tone: "bad" }); DO.app.render(); return; } } d[k] = v; audit("discipline", `changed ${k} of discipline ${d.code}`); st.commit(); saved(); });
  ui.on("ds-test", (el) => { const d = st.S.disciplines[+el.dataset.i]; const out = document.getElementById(`ds-t-${el.dataset.i}`); if (!el.value) { out.textContent = ""; return; } let ok = false; try { ok = new RegExp(d.regex).test(el.value.trim()); } catch (e) { /* */ } out.innerHTML = ok ? `<span class="ok-t">${icon("circle-check", 12)} passes</span>` : `<span class="danger-t">${icon("circle-x", 12)} fails</span>`; });
  ui.on("ds-add", () => ui.dialog({ title: "Add discipline", body: html`<form id="da-f" data-submit="ds-create" class="stack">${C.field("Code (one letter)", html`<input id="da-c" name="code" class="input mono" maxlength="1" required autofocus>`, { for: "da-c" })}${C.field("Name", html`<input id="da-n" name="name" class="input" required placeholder="e.g. Landscape">`, { for: "da-n" })}</form>`, foot: html`<button class="btn" data-close>Cancel</button><button class="btn primary" form="da-f">Add</button>` }));
  ui.on("ds-create", (f, d) => { const code = d.code.trim().toUpperCase(); if (!/^[A-Z]$/.test(code) || st.disc(code)) { ui.toast({ title: "Use a free single letter", tone: "bad" }); return; } st.S.disciplines.push({ code, name: d.name.trim(), regex: `^${code}-\\d{3}$`, order: st.S.disciplines.length, active: true }); audit("discipline", `added discipline ${code} ${d.name}`); ui.closeTop(); st.commit(); saved("Discipline added"); });

  function templates() {
    return html`${head("Stage templates", "Fee stages applied when a project is created. Percentages are placeholders until the owner confirms them (AS-05).", C.btn("New template", { variant: "primary", icon: "plus", act: "tp-add" }))}<div class="stack">${st.S.stageTemplates.map((t, ti) => { const tot = DO.sum(t.items, (x) => x.pct); return C.card({ title: t.name, actions: html`${t.isDefault ? html`<span class="pill ok">Default</span>` : C.btn("Make default", { size: "sm", act: "tp-default", data: { t: ti } })}${C.btn("Add stage", { size: "sm", icon: "plus", act: "tp-item", data: { t: ti } })}`, body: html`<div class="t-wrap"><table class="t"><thead><tr><th>#</th><th>Stage</th><th class="right">Fee %</th><th></th></tr></thead><tbody>${t.items.map((it, i) => html`<tr><td>${i + 1}</td><td><input class="input sm" value="${it.name}" data-change="tp-set" data-t="${ti}" data-i="${i}" data-k="name" aria-label="Stage ${i + 1} name"></td><td class="right"><input class="input sm right tabular" style="width:80px" value="${it.pct}" data-change="tp-set" data-t="${ti}" data-i="${i}" data-k="pct" aria-label="Stage ${i + 1} fee percent"></td><td>${C.btn("", { size: "sm", variant: "ghost", icon: "trash", act: "tp-del", data: { t: ti, i }, aria: "Remove stage" })}</td></tr>`)}</tbody><tfoot><tr><td></td><td class="strong">Total</td><td class="right strong" style="color:${Math.abs(tot - 100) < 0.01 ? "var(--ok-fg)" : "var(--danger)"}">${tot}%</td><td></td></tr></tfoot></table></div>` }); })}</div>`;
  }
  ui.on("tp-set", (el) => { const it = st.S.stageTemplates[+el.dataset.t].items[+el.dataset.i]; it[el.dataset.k] = el.dataset.k === "pct" ? +el.value || 0 : el.value; audit("template", "edited a stage template"); st.commit(); });
  ui.on("tp-item", (el) => { st.S.stageTemplates[+el.dataset.t].items.push({ name: "New stage", pct: 0 }); st.commit(); });
  ui.on("tp-del", (el) => { st.S.stageTemplates[+el.dataset.t].items.splice(+el.dataset.i, 1); st.commit(); });
  ui.on("tp-default", (el) => { st.S.stageTemplates.forEach((t, i) => { t.isDefault = i === +el.dataset.t; }); audit("template", "changed the default stage template"); st.commit(); saved(); });
  ui.on("tp-add", () => { st.S.stageTemplates.push({ id: st.nextId("tpl"), name: `Template ${st.S.stageTemplates.length + 1}`, isDefault: false, items: [{ name: "Design", pct: 50 }, { name: "Construction", pct: 50 }] }); st.commit(); saved("Template added"); });

  function codes() {
    const o = st.S.org;
    return html`${head("Revision and purpose codes", "Purpose is required to issue (F-08). The UI never uses the bare acronym “IFC”.")}<div class="grid g-2">${C.card({ title: "Revision scheme", body: html`<div class="card-body stack"><p class="small muted">Preliminary revisions before Working drawings, construction revisions from then on: P01, P02 … then C01, C02 (default, to confirm in discovery).</p>${o.revisionScheme.series.map((s, i) => html`<div class="form-grid">${C.field("Prefix", html`<input class="input mono" value="${s.prefix}" data-change="rv-set" data-i="${i}" data-k="prefix" maxlength="2" aria-label="Series ${i + 1} prefix">`)}${C.field("Label", html`<input class="input" value="${s.label}" data-change="rv-set" data-i="${i}" data-k="label" aria-label="Series ${i + 1} label">`)}</div>`)}${C.field("Digits", C.select({ options: [[2, "2 (P01)"], [3, "3 (P001)"]], value: o.revisionScheme.digits, change: "rv-digits" }))}<p class="small">Next codes for a Working-drawings sheet: ${C.mono(`C${String(1).padStart(o.revisionScheme.digits, "0")}`)}, ${C.mono(`C${String(2).padStart(o.revisionScheme.digits, "0")}`)}</p></div>` })}
      ${C.card({ title: "Purpose codes", actions: C.btn("Add", { size: "sm", icon: "plus", act: "pu-add" }), body: html`<div class="t-wrap"><table class="t"><thead><tr><th>Code</th><th>Label</th><th>Active</th></tr></thead><tbody>${o.purposes.map((x, i) => html`<tr><td><input class="input sm mono" style="width:70px" value="${x.code}" data-change="pu-set" data-i="${i}" data-k="code" aria-label="Code"></td><td><input class="input sm" value="${x.label}" data-change="pu-set" data-i="${i}" data-k="label" aria-label="Label"></td><td><input type="checkbox" ${x.active ? raw("checked") : ""} data-change="pu-set" data-i="${i}" data-k="active" aria-label="Active"></td></tr>`)}</tbody></table></div>` })}</div>
      ${C.card({ title: "ISO 19650 suitability codes (optional)", cls: "mt-4", body: html`<ul>${o.suitability.map((x) => html`<li class="list-row small"><span>${C.mono(x.code)} ${x.label}</span></li>`)}</ul>` })}`;
  }
  ui.on("rv-set", (el) => { st.S.org.revisionScheme.series[+el.dataset.i][el.dataset.k] = el.value.toUpperCase().slice(0, el.dataset.k === "prefix" ? 2 : 40); audit("codes", "changed the revision scheme"); st.commit(); saved(); });
  ui.on("rv-digits", (el) => { st.S.org.revisionScheme.digits = +el.value; st.commit(); saved(); });
  ui.on("pu-set", (el) => { const x = st.S.org.purposes[+el.dataset.i]; const k = el.dataset.k; const v = k === "active" ? el.checked : el.value; if (k === "label" && /^\s*IFC\s*$/i.test(v)) { ui.toast({ title: "Avoid the bare acronym “IFC”", description: "It also means a BIM file format. Use “Issued for Construction” or GFC.", tone: "bad" }); DO.app.render(); return; } x[k] = v; audit("codes", `changed purpose ${x.code}`); st.commit(); saved(); });
  ui.on("pu-add", () => { st.S.org.purposes.push({ code: "NEW", label: "New purpose", active: true }); st.commit(); });

  function naming() {
    const test = ui.state.nameTest ?? "A101 ground floor rev.pdf";
    const results = st.S.namingRules.map((r) => { let ok = false; let err = ""; try { ok = new RegExp(r.pattern).test(test); } catch (e) { err = e.message; } return { r, ok, err }; });
    return html`${head("Naming rules", "Uploaded PDFs that break a rule are blocked from issue with the rule text and a valid example (A-04, F-35).", C.btn("Add rule", { variant: "primary", icon: "plus", act: "nr-add" }))}
      ${C.card({ title: "Live tester", body: html`<div class="card-body stack-2"><label class="label" for="nr-test">Paste a file name or sheet number</label><input id="nr-test" class="input mono" value="${test}" data-input="nr-test" aria-describedby="nr-res"><ul id="nr-res" class="stack-2 mt-2" aria-live="polite">${results.map(({ r, ok, err }) => html`<li class="flex items-center gap-2 wrap">${ok ? html`<span class="pill ok">${icon("circle-check", 12)}Pass</span>` : html`<span class="pill bad">${icon("circle-x", 12)}Fail</span>`}<span class="small">${r.target === "file_name" ? "File name" : "Sheet number"} rule ${C.mono(r.pattern)}</span>${!ok ? html`<span class="small muted">${err || `${r.message} Example: ${r.example}`}</span>` : ""}</li>`)}</ul><p class="small muted">Try ${["A-101_C02.pdf", "A101.pdf", "M-205.pdf", "a-101_c02.pdf"].map((x) => html`<button class="link mono" data-act="nr-try" data-v="${x}">${x}</button> `)}</p></div>` })}
      ${C.card({ title: "Rules", cls: "mt-4", body: html`<div class="t-wrap"><table class="t"><thead><tr><th>Applies to</th><th>Pattern (regex)</th><th>Message</th><th>Valid example</th><th>Scope</th><th></th></tr></thead><tbody>${st.S.namingRules.map((r, i) => html`<tr><td>${C.select({ options: [["file_name", "File name"], ["sheet_number", "Sheet number"]], value: r.target, change: "nr-set", dataset: { i, k: "target" }, cls: "sm", aria: "Target" })}</td><td><input class="input sm mono" value="${r.pattern}" data-change="nr-set" data-i="${i}" data-k="pattern" aria-label="Pattern"></td><td><input class="input sm" value="${r.message}" data-change="nr-set" data-i="${i}" data-k="message" aria-label="Message"></td><td><input class="input sm mono" style="width:130px" value="${r.example}" data-change="nr-set" data-i="${i}" data-k="example" aria-label="Example"></td><td>${C.select({ options: [["org", "Whole firm"], ...st.S.projects.map((p) => [p.id, `Only ${p.code}`])], value: r.scope, change: "nr-set", dataset: { i, k: "scope" }, cls: "sm", aria: "Scope" })}</td><td>${C.btn("", { size: "sm", variant: "ghost", icon: "trash", act: "nr-del", data: { i }, aria: "Delete rule" })}</td></tr>`)}</tbody></table></div>`, foot: "Rules are per firm and can be overridden per project." })}`;
  }
  ui.on("nr-test", (el) => { ui.state.nameTest = el.value; DO.app.render(); });
  ui.on("nr-try", (el) => { ui.state.nameTest = el.dataset.v; DO.app.render(); });
  ui.on("nr-set", (el) => { const r = st.S.namingRules[+el.dataset.i]; if (el.dataset.k === "pattern") { try { new RegExp(el.value); } catch (e) { ui.toast({ title: "Invalid regular expression", description: e.message, tone: "bad" }); DO.app.render(); return; } } r[el.dataset.k] = el.value; audit("naming", `changed a naming rule (${el.dataset.k})`); st.commit(); saved(); });
  ui.on("nr-add", () => { st.S.namingRules.push({ id: st.nextId("nr"), target: "file_name", pattern: "^.+\\.pdf$", message: "Upload PDFs only.", example: "A-101.pdf", scope: "org" }); st.commit(); });
  ui.on("nr-del", (el) => { st.S.namingRules.splice(+el.dataset.i, 1); audit("naming", "deleted a naming rule"); st.commit(); });

  function checklists() {
    return html`${head("Checklists", "Designer pre-check lists per discipline and stage (F-13). If attached, Submit for check is blocked until every required item is ticked.", C.btn("New checklist", { variant: "primary", icon: "plus", act: "cl-add" }))}<div class="stack">${st.S.checklists.map((c, ci) => C.card({ title: c.name, actions: html`${C.select({ options: st.S.disciplines.map((d) => [d.code, d.name]), value: c.discipline, change: "cl-set", dataset: { c: ci, k: "discipline" }, cls: "sm", aria: "Discipline" })}${C.select({ options: [...new Set(st.S.stages.map((x) => x.name))].map((n) => [n, n]), value: c.stage, change: "cl-set", dataset: { c: ci, k: "stage" }, cls: "sm", aria: "Stage" })}${C.btn("", { size: "sm", variant: "ghost", icon: "trash", act: "cl-del", data: { c: ci }, aria: "Delete checklist" })}`, body: html`<ul>${c.items.map((it, i) => html`<li class="list-row"><input class="input sm grow" value="${it.text}" data-change="cl-item" data-c="${ci}" data-i="${i}" data-k="text" aria-label="Item ${i + 1}"><label class="check small"><input type="checkbox" ${it.mandatory ? raw("checked") : ""} data-change="cl-item" data-c="${ci}" data-i="${i}" data-k="mandatory">Required</label>${C.btn("", { size: "sm", variant: "ghost", icon: "x", act: "cl-item-del", data: { c: ci, i }, aria: "Remove item" })}</li>`)}</ul>`, foot: html`${C.btn("Add item", { size: "sm", icon: "plus", act: "cl-item-add", data: { c: ci } })}<span>Used on ${st.S.sheets.filter((s) => s.discipline === c.discipline && st.stage(s.stageId)?.name === c.stage).length} sheets</span>` }))}</div>`;
  }
  ui.on("cl-set", (el) => { st.S.checklists[+el.dataset.c][el.dataset.k] = el.value; st.commit(); saved(); });
  ui.on("cl-item", (el) => { const it = st.S.checklists[+el.dataset.c].items[+el.dataset.i]; it[el.dataset.k] = el.dataset.k === "mandatory" ? el.checked : el.value; st.commit(); });
  ui.on("cl-item-add", (el) => { st.S.checklists[+el.dataset.c].items.push({ text: "New check", mandatory: false }); st.commit(); });
  ui.on("cl-item-del", (el) => { st.S.checklists[+el.dataset.c].items.splice(+el.dataset.i, 1); st.commit(); });
  ui.on("cl-del", (el) => { st.S.checklists.splice(+el.dataset.c, 1); st.commit(); });
  ui.on("cl-add", () => { st.S.checklists.push({ id: st.nextId("cl"), name: "Electrical GFC pre-check", discipline: "E", stage: "Working drawings / GFC", items: [{ text: "Panel schedule loads match the SLD", mandatory: true }] }); st.commit(); });

  function intelligence() {
    const i = st.S.org.intelligence; const gate = i.historyMonths >= 6 && i.issuedRevisions >= 2000;
    return html`${head("Intelligence", "Advisory forecasts and drawing checks (Phase 4). They never change data; every screen labels them “Forecast”.")}
      ${C.card({ title: "Gate G3: enough clean history", body: html`<div class="card-body stack-2"><p>${gate ? html`<span class="pill ok">${icon("circle-check", 12)}Passed</span>` : html`<span class="pill warn">Waiting</span>`} Phase 4 runs only with at least 6 months of history and 2,000 issued revisions.</p><p class="small">History ${i.historyMonths} months ${C.bar(Math.min(100, (i.historyMonths / 6) * 100), "ok")} · issued revisions ${DO.fmtNum(i.issuedRevisions)} ${C.bar(Math.min(100, (i.issuedRevisions / 2000) * 100), "ok")}</p></div>` })}
      <div class="grid g-3 mt-4">
        ${C.card({ title: "Late-risk prediction (F-55)", body: html`<div class="card-body stack-2">${C.seg("Late risk", [["on", "On"], ["off", "Off"]], i.lateRisk, "in-set-lr")}<p class="small">Back-test on a held-out month: precision of the top 20% ${Math.round(i.precisionMeasured * 100)}% vs ${Math.round((i.precisionMeasured / 2.2) * 100)}% for A-01 alone (2.2× better; target 2×).</p></div>` })}
        ${C.card({ title: "Workload forecast (F-56)", body: html`<div class="card-body stack-2">${C.seg("Forecast", [["on", "On"], ["off", "Off"]], i.forecast, "in-set-fc")}<table class="t"><thead><tr><th>Discipline</th><th class="right">MAPE</th></tr></thead><tbody>${["A", "M", "E", "P", "F", "S"].map((d) => html`<tr><td>${st.disc(d).name}</td><td class="right">${st.mape(d)}%</td></tr>`)}</tbody></table></div>` })}
        ${C.card({ title: "AI drawing checks (F-57)", body: html`<div class="card-body stack-2">${C.seg("Drawing checks", [["off", "Off"], ["evaluation", "Evaluation"], ["on", "On"]], i.drawingChecks, "in-set-dc")}<p class="small">“On” needs at least 200 labelled sheets (${i.labelled} labelled) and the precision target agreed with the owner (${Math.round(i.precisionTarget * 100)}%; measured ${Math.round(i.precisionMeasured * 100)}%). A person approves every finding.</p><a class="link small" href="#/intelligence/findings">Findings queue (${st.S.findings.filter((f) => f.status === "open").length} open)</a></div>` })}
      </div>`;
  }
  ui.on("in-set-lr", (el) => { st.S.org.intelligence.lateRisk = el.dataset.v; audit("intelligence", `turned late-risk prediction ${el.dataset.v}`); st.commit(); saved(); });
  ui.on("in-set-fc", (el) => { st.S.org.intelligence.forecast = el.dataset.v; st.commit(); saved(); });
  ui.on("in-set-dc", (el) => { const i = st.S.org.intelligence; if (el.dataset.v === "on" && i.labelled < 200) { ui.toast({ title: "Needs 200 labelled sheets first", tone: "bad" }); return; } i.drawingChecks = el.dataset.v; audit("intelligence", `set AI drawing checks to ${el.dataset.v}`); st.commit(); saved(); });

  function calendar() {
    const o = st.S.org; const hol = st.S.holidays.slice().sort(DO.by("date"));
    return html`${head("Working calendar", "Working days drive every automation: at-risk windows, late counts, review waiting and timesheet weeks (F-42).")}<div class="grid g-2">${C.card({ title: "Working week", body: html`<div class="card-body flex wrap gap-2">${[1, 2, 3, 4, 5, 6, 0].map((d) => html`<label class="fchip"><input type="checkbox" ${o.workdays.includes(d) ? raw("checked") : ""} data-change="cal-day" data-d="${d}">${DO.DAYS[d]}</label>`)}</div>`, foot: `Today is ${DO.isWorkingDay(DO.today()) ? "a working day" : "not a working day"}.` })}
      ${C.card({ title: `Holidays · ${hol.length}`, body: html`<ul>${hol.map((h) => html`<li class="list-row"><span><span class="tabular">${DO.fmtDate(h.date)}</span> · ${h.name} <span class="small muted">${DO.DAYS[DO.weekday(h.date)]}</span></span>${C.btn("", { size: "sm", variant: "ghost", icon: "trash", act: "cal-del", data: { d: h.date }, aria: `Remove ${h.name}` })}</li>`)}</ul><form data-submit="cal-add" class="flex wrap gap-2 p-3" style="border-top:1px solid var(--border)"><input type="date" name="date" class="input sm" style="width:160px" required aria-label="Holiday date"><input name="name" class="input sm" style="width:200px" placeholder="Holiday name" required aria-label="Holiday name"><button class="btn sm">${icon("plus", 14)}Add holiday</button></form>`, foot: "Sample calendar for the demo; confirm the firm's list in discovery." })}</div>`;
  }
  const recal = () => DO.setCalendar(st.S.org.workdays, st.S.holidays.map((h) => h.date));
  ui.on("cal-day", (el) => { const d = +el.dataset.d; const w = st.S.org.workdays; st.S.org.workdays = el.checked ? [...new Set([...w, d])].sort() : w.filter((x) => x !== d); recal(); audit("calendar", "changed the working week"); st.commit(); saved("Working week saved"); });
  ui.on("cal-add", (f, d) => { if (st.S.holidays.some((h) => h.date === d.date)) { ui.toast({ title: "That date is already a holiday", tone: "bad" }); return; } st.S.holidays.push({ date: d.date, name: d.name.trim() }); recal(); audit("calendar", `added holiday ${d.name} on ${DO.fmtDate(d.date)}`); st.commit(); saved("Holiday added"); });
  ui.on("cal-del", (el) => { st.S.holidays = st.S.holidays.filter((h) => h.date !== el.dataset.d); recal(); audit("calendar", `removed the holiday on ${DO.fmtDate(el.dataset.d)}`); st.commit(); });

  function automation() {
    const R = st.S.org.rules;
    const rules = [["A-01", "At risk", "Daily 08:00", "Planned issue date within N working days and not started / in progress", [["days", "N working days"]]], ["A-02", "Late", "Daily 08:00", "Planned date passed with no issued revision; escalate after N working days", [["escalate", "Escalate after"]]], ["A-03", "Supersede and tell earlier recipients", "On issue", "Earlier revision superseded; previous recipients emailed", []], ["A-04", "Naming rule check", "On upload", "Block issue when the file name or sheet number breaks a rule", []], ["A-05", "Over / under-allocated", "Monday 07:00", "Allocations above / below % of capacity", [["over", "Over %"], ["under", "Under %"]]], ["A-06", "Timesheet missing", "Tuesday 12:00", "No submitted timesheet for the previous week", []], ["A-07", "Review overdue", "Daily 08:00", "Review open more than N working days: escalate to delegate or DL", [["days", "N working days"]]], ["A-08", "Client comment overdue", "Daily 08:00", "No response after N days", [["days", "N days"]]], ["A-09", "Ready to invoice", "On issue / approval", "All deliverables issued and client approval recorded", []], ["A-10", "RFI due", "Daily 08:00", "RFI response due within N working days", [["days", "N working days"]]]];
    const runs = st.S.automationRuns.slice().reverse().slice(0, 12);
    const todayRun = runs.find((r) => DO.dateOf(r.at) === DO.today() && /Daily/.test(r.rule));
    return html`${head("Automation", "Thresholds are placeholders to agree with the owner. Sweeps are idempotent: running twice raises no duplicates.", C.btn("Run the daily sweep now", { variant: "primary", icon: "refresh-cw", act: "au-run" }))}
      ${todayRun ? html`<p class="alert ok mb-3">${icon("circle-check", 16)}<span>Today's 08:00 sweep ran at ${DO.fmtTime(todayRun.at)} in ${todayRun.durationMs} ms.</span></p>` : html`<p class="alert warn mb-3">${icon("triangle-alert", 16)}<span>No daily sweep has run today. After 09:00 an alert goes to the admin (N-05).</span></p>`}
      ${C.card({ body: html`<div class="t-wrap"><table class="t"><thead><tr><th>Rule</th><th>When</th><th>Condition</th><th>Thresholds</th><th>On</th></tr></thead><tbody>${rules.map(([id, name, when, cond, params]) => html`<tr><td>${C.mono(id)} <span class="strong">${name}</span></td><td class="small nowrap">${when}</td><td class="small">${cond}</td><td>${params.map(([k, l]) => html`<label class="flex items-center gap-2 small mb-1">${l}<input type="number" class="input sm" style="width:70px" value="${R[id][k]}" data-change="au-set" data-id="${id}" data-k="${k}" aria-label="${id} ${l}"></label>`)}</td><td><input type="checkbox" ${R[id].on ? raw("checked") : ""} data-change="au-on" data-id="${id}" aria-label="${id} enabled"></td></tr>`)}</tbody></table></div>` })}
      ${C.card({ title: "Run log", cls: "mt-4", body: html`<div class="t-wrap"><table class="t"><thead><tr><th>When</th><th>Run</th><th class="right">Duration</th><th>Counts</th></tr></thead><tbody>${runs.map((r) => html`<tr><td class="nowrap">${DO.fmtDateTime(r.at)}</td><td>${r.rule}${r.by ? html`<span class="small muted block">by ${st.userName(r.by)}</span>` : ""}</td><td class="right tabular">${r.durationMs} ms</td><td class="small">${Object.entries(r.counts).map(([k, v]) => `${k.replace(/_/g, " ")} ${v}`).join(" · ")}</td></tr>`)}</tbody></table></div>` })}`;
  }
  ui.on("au-set", (el) => { const v = +el.value; if (!(v >= 0)) return; st.S.org.rules[el.dataset.id][el.dataset.k] = v; audit("automation", `set ${el.dataset.id} ${el.dataset.k} to ${v}`); st.commit(); saved("Threshold saved: flags recalculated"); });
  ui.on("au-on", (el) => { st.S.org.rules[el.dataset.id].on = el.checked; audit("automation", `${el.checked ? "enabled" : "disabled"} ${el.dataset.id}`); st.commit(); saved(); });
  ui.on("au-run", () => { const r = st.runSweep(); ui.toast({ title: "Sweep finished", description: `${r.counts.at_risk_raised} at risk, ${r.counts.late_raised} late, ${r.counts.reviews_overdue} reviews overdue, ${r.counts.duplicates_skipped} duplicates skipped.`, tone: "ok", timeout: 8000 }); });

  function users(u) {
    const list = st.S.users.slice().sort(DO.by("name")); const inv = st.S.invitations.filter((i) => !i.accepted);
    return html`${head("Users and roles", "Organisation role here; project roles are set by each project lead (F-38). Admins sign in with a local account and TOTP 2FA.", C.btn("Invite user", { variant: "primary", icon: "user-plus", act: "us-invite" }))}
      ${inv.length ? C.card({ title: `Invitations waiting · ${inv.length}`, cls: "mb-4", body: html`<ul>${inv.map((i) => html`<li class="list-row"><span>${i.name} · ${i.email}<span class="small muted block">${i.orgRole} · sent ${DO.fmtDateTime(i.sentAt)} by ${st.userName(i.by)}</span></span><span class="actions">${C.linkBtn("Open invitation link", `#/invite/${i.token}`, { size: "sm" })}${C.btn("Resend", { size: "sm", act: "us-resend", data: { id: i.id } })}${C.btn("Withdraw", { size: "sm", variant: "danger", act: "us-withdraw", data: { id: i.id } })}</span></li>`)}</ul>` }) : ""}
      ${C.card({ body: html`<div class="t-wrap"><table class="t"><thead><tr><th>Name</th><th>Org role</th><th class="hide-sm">Discipline</th><th class="hide-md">Sign-in</th><th class="hide-md">Projects</th><th class="hide-md">Last seen</th><th>Status</th></tr></thead><tbody>${list.map((x) => html`<tr><td>${x.name}<span class="small muted block">${x.email}</span></td><td>${C.select({ options: [["owner", "Owner"], ["staff", "Staff"], ["accounts", "Accounts"], ["admin", "Admin"]], value: x.orgRole, change: "us-role", dataset: { id: x.id }, cls: "sm", aria: `Org role for ${x.name}`, disabled: x.id === u.id })}</td><td class="hide-sm">${x.discipline || html`<span class="muted">—</span>`}</td><td class="hide-md small">${x.mfa ? html`${icon("key-round", 12)} Password + TOTP` : html`${icon("shield-check", 12)} Microsoft SSO`}</td><td class="hide-md small">${st.S.projects.filter((p) => st.rolesOn(x, p).length).length}</td><td class="hide-md small">${x.lastSeen ? DO.fmtRel(x.lastSeen) : "Never"}</td><td>${x.id === u.id ? html`<span class="pill ok">You</span>` : C.btn(x.active ? "Deactivate" : "Reactivate", { size: "sm", variant: x.active ? "ghost" : "primary", act: "us-active", data: { id: x.id } })}</td></tr>`)}</tbody></table></div>`, foot: "First SSO sign-in creates a user with no project access until a project lead adds them." })}`;
  }
  ui.on("us-role", (el) => { const x = st.user(el.dataset.id); const before = x.orgRole; x.orgRole = el.value; x.mfa = el.value === "admin" || x.mfa; st.audit("user", x.id, "role", { orgRole: before }, { orgRole: x.orgRole }, { text: `${DO.auth.current().name} changed ${x.name}'s organisation role from ${before} to ${x.orgRole}` }); st.commit(); saved("Role changed"); });
  ui.on("us-active", async (el) => { const x = st.user(el.dataset.id); if (x.active) { const ok = await ui.confirm({ title: `Deactivate ${x.name}?`, body: "They can no longer sign in. Their history, sheets and hours stay. Reassign their open sheets afterwards.", confirm: "Deactivate", danger: true }); if (!ok) return; } x.active = !x.active; st.audit("user", x.id, x.active ? "reactivated" : "deactivated", null, null, { text: `${DO.auth.current().name} ${x.active ? "reactivated" : "deactivated"} ${x.name}` }); st.commit(); saved(x.active ? "Reactivated" : "Deactivated"); });
  ui.on("us-invite", () => ui.dialog({ title: "Invite a user", subtitle: "They get an email (in the demo mailbox) to set up their account. No public sign-up.", body: html`<form id="iv-f" data-submit="us-invite-send" class="stack">${C.field("Full name", html`<input id="iv-nn" name="name" class="input" required autofocus>`, { for: "iv-nn" })}${C.field("Email", html`<input id="iv-em" name="email" type="email" class="input" required placeholder="name@firm.example">`, { for: "iv-em" })}<div class="form-grid">${C.field("Organisation role", C.select({ id: "iv-r", name: "role", options: [["staff", "Staff"], ["accounts", "Accounts"], ["owner", "Owner"], ["admin", "Admin (2FA required)"]] }), { for: "iv-r" })}${C.field("Discipline", C.select({ id: "iv-d", name: "disc", options: [["", "—"], ...st.S.disciplines.map((d) => [d.code, d.name])] }), { for: "iv-d" })}</div></form>`, foot: html`<button class="btn" data-close>Cancel</button><button class="btn primary" form="iv-f">Send invitation</button>` }));
  ui.on("us-invite-send", (f, d) => { const email = d.email.trim().toLowerCase(); if (!/^\S+@\S+\.\S+$/.test(email)) { ui.toast({ title: "Enter a valid email", tone: "bad" }); return; } if (st.S.users.some((x) => x.email === email)) { ui.toast({ title: "That person already has an account", tone: "bad" }); return; } const i = { id: st.nextId("in"), name: d.name.trim(), email, orgRole: d.role, discipline: d.disc, token: `inv-${Math.random().toString(36).slice(2, 10)}`, sentAt: new Date().toISOString(), by: DO.auth.current().id, accepted: false }; st.S.invitations.push(i); st.sendEmail({ to: [email], toName: i.name, subject: `You're invited to DrawingOps at ${st.S.org.name}`, body: `Hello ${i.name.split(" ")[0]},\n\n${DO.auth.current().name} invited you to DrawingOps. Accept the invitation to set up your account.`, link: `#/invite/${i.token}`, kind: "invite" }); st.audit("user", email, "invited", null, { role: d.role }, { text: `${DO.auth.current().name} invited ${i.name} (${email}) as ${d.role}` }); ui.closeTop(); st.commit(); ui.toast({ title: `Invitation sent to ${email}`, description: "Open the demo mailbox to accept it as them.", tone: "ok", action: { label: "Mailbox", run: () => DO.app.go("/mailbox") } }); });
  ui.on("us-resend", (el) => { const i = st.S.invitations.find((x) => x.id === el.dataset.id); i.sentAt = new Date().toISOString(); st.sendEmail({ to: [i.email], toName: i.name, subject: `Reminder: your DrawingOps invitation`, body: `Hello ${i.name.split(" ")[0]},\n\nYour invitation is waiting.`, link: `#/invite/${i.token}`, kind: "invite" }); st.commit(); ui.toast({ title: "Invitation resent", tone: "ok" }); });
  ui.on("us-withdraw", (el) => { st.S.invitations = st.S.invitations.filter((x) => x.id !== el.dataset.id); st.commit(); ui.toast({ title: "Invitation withdrawn" }); });

  function integrations(u) {
    const o = st.S.org; const t = ui.state.newToken;
    const row = (name, phase, status, tone, desc, action) => html`<li class="list-row" style="align-items:flex-start"><span class="min-w-0"><span class="strong">${name}</span> <span class="small muted">${phase}</span><span class="small muted block">${desc}</span></span><span class="flex gap-2 items-center wrap"><span class="pill ${tone}">${status}</span>${action || ""}</span></li>`;
    return html`${head("Integrations", "Connections to the firm's tools. In this demo none of them makes a network request.")}
      ${t ? html`<p class="alert ok mb-3">${icon("key-round", 16)}<span>New token for “${t.name}”: <code class="mono">${t.secret}</code>. Copy it now: it is shown once.</span></p>` : ""}
      <div class="stack">
      ${C.card({ title: "Sign-in and email", body: html`<ul>${row("Single sign-on: Microsoft 365 (OIDC)", "I-11 · P1", "Connected", "ok", `Tenant ${o.sso.tenant}. Google Workspace is also supported.`, "")}${row("Local accounts with TOTP 2FA", "F-40", "On for admins", "ok", "Fallback for people without a firm account.", "")}${row("Outbound email", "I-12 · P1", "Demo mailbox", "warn", "In production: the firm's SMTP relay or a transactional email service. Here every email goes to the demo mailbox.", C.linkBtn("Open mailbox", "#/mailbox", { size: "sm" }))}${row("Inbound email for client comments", "I-09 · P2", "Connected", "ok", "Each project has an address like p-2026-014@in.drawingops.example; webhook secret required.", "")}</ul>` })}
      ${C.card({ title: "CAD and files", body: html`<ul>${row("Revit add-in", "I-04 · P2", "Connected", "ok", "Sheet list and revisions from the model; proposals wait for DL approval.", C.linkBtn("CAD sync", "#/projects/p1/cad-sync", { size: "sm" }))}${row("AutoCAD plugin", "I-03 · P2", "Connected", "ok", "Sheet Set title-block fields.", "")}${row("File-storage connector", "I-02 · P2", "Partly built", "warn", "The receiving API is live; the watcher for the office server / Google Drive / SharePoint / Egnyte needs the firm's storage choice (P0-05).", "")}${row("Autodesk Forma", "I-05", "Conditional", "", "Only if the firm uses Forma.", "")}${row("Bluebeam Studio", "I-06", "Conditional", "", "Needs confirmed developer access in India.", "")}${row("Navisworks / BCF clash import", "I-07 · P3", "Available", "ok", "Import from Construction › Clashes.", "")}</ul>` })}
      ${C.card({ title: "Accounting (F-28, I-08)", body: html`<div class="card-body stack"><p class="small muted">CSV of ready stages in the column layout agreed with the firm, then a signed webhook. Invoicing and GST stay in the accounting tool.</p><div class="field"><span class="label">CSV columns (in order)</span><div class="flex wrap gap-2">${["project_code", "project_name", "client", "stage", "fee_pct", "fee_amount", "ready_date", "days_waiting", "approved_by", "approved_on"].map((c) => html`<label class="fchip"><input type="checkbox" ${o.billingColumns.includes(c) ? raw("checked") : ""} data-change="ig-col" data-c="${c}">${c}</label>`)}</div></div><div class="form-grid">${C.field("Webhook URL", html`<input id="ig-wh" class="input mono" value="${o.webhook.url}" data-change="ig-wh">`, { for: "ig-wh", hint: "Private and link-local addresses are refused (SSRF guard)." })}<div class="field"><span class="label">Webhook</span><label class="check"><input type="checkbox" ${o.webhook.enabled ? raw("checked") : ""} data-change="ig-wh-on">Enabled</label>${o.webhook.lastStatus ? html`<span class="small muted">Last push: ${o.webhook.lastStatus}</span>` : ""}</div></div>${C.btn("Send a test event", { size: "sm", icon: "webhook", act: "ig-test" })}</div>` })}
      ${C.card({ title: "API tokens", actions: C.btn("New token", { size: "sm", icon: "plus", act: "tk-new" }), body: html`<ul>${st.S.tokens.map((k) => html`<li class="list-row"><span>${k.name}<span class="small muted block">${C.mono(`${k.prefix}…`)} · scope ${C.mono(k.scope)} · created ${DO.fmtDate(k.createdAt)} · last used ${k.lastUsed ? DO.fmtRel(k.lastUsed) : "never"}</span></span>${C.btn("Revoke", { size: "sm", variant: "danger", act: "tk-revoke", data: { id: k.id } })}</li>`)}</ul>` })}
      ${C.card({ title: "Decisions pending", body: html`<ul>${row("WhatsApp Business API", "I-10", "Decision pending", "", "Privacy and consent to decide at G1 (DEC-09). Default: not built.", "")}${row("Paperless-ngx sidecar archive", "I-13", "Decision pending", "", "Links to scanned approvals and letters; decision DEC-10.", "")}</ul>` })}
      </div>`;
  }
  ui.on("ig-col", (el) => { const o = st.S.org; o.billingColumns = el.checked ? [...new Set([...o.billingColumns, el.dataset.c])] : o.billingColumns.filter((c) => c !== el.dataset.c); st.commit(); saved("Column layout saved"); });
  ui.on("ig-wh", (el) => { const v = el.value.trim(); if (!/^https:\/\//.test(v) || /\/\/(localhost|127\.|10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.)/.test(v)) { ui.toast({ title: "Use a public https:// address", description: "Private, loopback and link-local addresses are refused (SSRF guard, DD-029).", tone: "bad" }); DO.app.render(); return; } st.S.org.webhook.url = v; st.commit(); saved(); });
  ui.on("ig-wh-on", (el) => { st.S.org.webhook.enabled = el.checked; st.commit(); saved(); });
  ui.on("ig-test", () => { st.S.org.webhook.lastStatus = `200 OK (simulated test) · ${DO.fmtDateTime(new Date())}`; st.commit(); ui.toast({ title: "Test event sent (simulated)", description: "No network request was made in the demo.", tone: "ok" }); });
  ui.on("tk-new", () => ui.dialog({ title: "New API token", body: html`<form id="tk-f" data-submit="tk-create" class="stack">${C.field("Name", html`<input id="tk-n" name="name" class="input" required autofocus placeholder="e.g. Revit add-in - Structure team">`, { for: "tk-n" })}${C.field("Scope", C.select({ id: "tk-s", name: "scope", options: [["sheets:sync", "sheets:sync (CAD plugins)"], ["file_events:write", "file_events:write (storage watcher)"], ["billing:read", "billing:read (accounting)"]] }), { for: "tk-s" })}</form>`, foot: html`<button class="btn" data-close>Cancel</button><button class="btn primary" form="tk-f">Create token</button>` }));
  ui.on("tk-create", (f, d) => { const secret = `do_live_${Math.random().toString(36).slice(2, 6)}${Math.random().toString(36).slice(2, 14)}`; st.S.tokens.push({ id: st.nextId("tk"), name: d.name.trim(), scope: d.scope, prefix: secret.slice(0, 12), createdAt: new Date().toISOString(), lastUsed: null, by: DO.auth.current().id }); ui.state.newToken = { name: d.name.trim(), secret }; st.audit("token", d.name, "created", null, { scope: d.scope }, { text: `${DO.auth.current().name} created API token “${d.name.trim()}” (${d.scope})` }); ui.closeTop(); st.commit(); });
  ui.on("tk-revoke", async (el) => { const ok = await ui.confirm({ title: "Revoke this token?", body: "Plugins using it stop syncing immediately.", confirm: "Revoke", danger: true }); if (!ok) return; st.S.tokens = st.S.tokens.filter((k) => k.id !== el.dataset.id); ui.state.newToken = null; st.commit(); });

  // ---------- F-54 Onboarding of a live project ----------
  function onboarding() {
    const ob = ui.state.ob || {};
    return html`${head("Onboarding", "Load a live project in under an hour: projects, stages, sheets and past revisions from a workbook and a folder of PDFs. Nothing sends notifications during import.")}
      ${C.card({ body: html`<div class="card-body stack"><ol class="stack-2"><li>1. Download the template: <a class="link" href="assets/documents/onboarding-template.xlsx" download>onboarding-template.xlsx</a> (already filled with a sample live project).</li><li>2. Upload the filled workbook and the folder of issued PDFs.</li><li>3. Fix the problems listed, then load the project.</li></ol>
        <div class="form-grid"><label class="dropzone" for="ob-x">${icon("file-spreadsheet", 24, "primary-t")}<span class="strong">${ob.file ? ob.file : "Workbook (.xlsx or .csv)"}</span><input id="ob-x" type="file" class="sr-only" accept=".xlsx,.csv" data-change="ob-file"></label><label class="dropzone" for="ob-p">${icon("folder-open", 24, "primary-t")}<span class="strong">${ob.pdfs?.length ? `${ob.pdfs.length} PDFs` : "Folder of PDFs (optional)"}</span><input id="ob-p" type="file" class="sr-only" multiple accept=".pdf" data-change="ob-pdfs"></label></div>
        ${C.btn("Use the sample workbook", { size: "sm", act: "ob-sample" })}</div>` })}
      ${ob.rows ? C.card({ title: `Check · ${ob.project?.code || "?"} ${ob.project?.name || ""}`, cls: "mt-4", body: html`<div class="card-body stack-2">${ob.problems.length ? html`<p class="alert bad">${icon("circle-alert", 16)}<span>${DO.plural(ob.problems.length, "problem")} to fix first.</span></p><ul class="small stack-2">${ob.problems.map((x) => html`<li class="danger-t">${x}</li>`)}</ul>` : html`<p class="alert ok">${icon("circle-check", 16)}<span>Ready: ${DO.plural(ob.sheets.length, "sheet")} and ${DO.plural(ob.rows.length, "revision")} (${ob.rows.filter((r) => r.state === "issued").length} current, ${ob.rows.filter((r) => r.state === "superseded").length} superseded) with original dates.${ob.pdfs?.length ? ` ${ob.matched} of ${ob.pdfs.length} PDFs matched by file name.` : ""}</span></p>`}</div>`, foot: html`<span>No emails or notifications are sent during onboarding.</span>${C.btn("Load project", { variant: "primary", icon: "database", act: "ob-load", disabled: !!ob.problems.length || ob.done })}` }) : ""}
      ${ob.done ? html`<p class="alert ok mt-3">${icon("circle-check", 16)}<span>Loaded. <a class="link" href="#/projects/${ob.done}/register">Open the register</a>.</span></p>` : ""}`;
  }
  async function obRead(rows, name) {
    const hdr = rows[0].map((h) => String(h).toLowerCase()); const col = (k) => hdr.findIndex((h) => h.includes(k));
    const c = { code: col("project code"), name: col("project name"), client: col("client"), num: col("sheet"), title: col("title"), disc: col("discipline"), rev: col("revision"), date: col("date"), purpose: col("purpose"), file: col("file") };
    const problems = []; const data = rows.slice(1).map((r, i) => ({ line: i + 2, code: r[c.code], name: r[c.name], client: r[c.client], number: String(r[c.num] || "").trim().toUpperCase(), title: r[c.title], disc: String(r[c.disc] || "").trim().toUpperCase(), rev: String(r[c.rev] || "").trim().toUpperCase(), date: String(r[c.date] || "").trim(), purpose: String(r[c.purpose] || "").trim().toUpperCase(), file: r[c.file] }));
    const code = data[0]?.code; if (!code) problems.push("Project code missing in the first data row.");
    if (st.S.projects.some((p) => p.code === code)) problems.push(`Project ${code} already exists.`);
    data.forEach((r) => { if (!/^[A-Z]-\d{3}$/.test(r.number)) problems.push(`Row ${r.line}: sheet number “${r.number}” breaks the rule (e.g. A-101).`); if (!st.disc(r.disc)) problems.push(`Row ${r.line}: unknown discipline “${r.disc}”.`); if (!/^[PC]\d{2}$/.test(r.rev)) problems.push(`Row ${r.line}: revision “${r.rev}” is not P01/C01 style.`); if (!/^\d{4}-\d{2}-\d{2}$/.test(r.date)) problems.push(`Row ${r.line}: date “${r.date}” should be YYYY-MM-DD.`); if (!st.S.org.purposes.some((p) => p.code === r.purpose)) problems.push(`Row ${r.line}: purpose “${r.purpose}” is not in the purpose list.`); });
    const sheets = [...new Set(data.map((r) => r.number))];
    sheets.forEach((n) => { const revs = data.filter((r) => r.number === n).sort((a, b) => (a.date > b.date ? 1 : -1)); revs.forEach((r, i) => { r.state = i === revs.length - 1 ? "issued" : "superseded"; }); });
    const ob = { file: name, rows: data, sheets, problems: problems.slice(0, 20), project: { code, name: data[0]?.name, client: data[0]?.client }, pdfs: ui.state.ob?.pdfs || [] };
    ob.matched = ob.pdfs.filter((f) => data.some((r) => r.file === f.name)).length;
    ui.state.ob = ob; DO.app.render();
  }
  ui.on("ob-file", async (el) => { const f = el.files?.[0]; if (!f) return; try { const rows = /\.csv$/i.test(f.name) ? DO.parseCSV(await f.text()) : await DO.zip.readXlsx(new Uint8Array(await f.arrayBuffer())); await obRead(rows, f.name); } catch (e) { ui.toast({ title: "Could not read the workbook", description: e.message, tone: "bad" }); } });
  ui.on("ob-pdfs", (el) => { ui.state.ob = { ...(ui.state.ob || {}), pdfs: [...el.files] }; if (ui.state.ob.rows) ui.state.ob.matched = ui.state.ob.pdfs.filter((f) => ui.state.ob.rows.some((r) => r.file === f.name)).length; DO.app.render(); });
  ui.on("ob-sample", async () => { try { if (location.protocol === "file:") throw new Error("file"); const res = await fetch("assets/documents/onboarding-template.csv"); if (!res.ok) throw new Error(); await obRead(DO.parseCSV(await res.text()), "onboarding-template (sample)"); } catch (e) { await obRead(DO.parseCSV(DO.ONBOARD_CSV), "onboarding-template (sample)"); } });
  ui.on("ob-load", () => {
    const ob = ui.state.ob; const u = DO.auth.current(); const id = st.nextId("p");
    const p = { id, code: ob.project.code, name: ob.project.name, description: "Onboarded live project", type: "other", clientId: null, client: ob.project.client, location: "", start: ob.rows.map((r) => r.date).sort()[0], end: DO.addDays(DO.today(), 300), fee: 0, cad: ["AutoCAD 2024"], state: "active", leadId: "u_pl", members: [{ userId: "u_pl", role: "PL", discipline: "" }, { userId: "u_dc", role: "DC", discipline: "" }], letter: null, projectEmail: `p-${ob.project.code}@in.drawingops.example`, createdAt: new Date().toISOString(), recipients: [], siteToken: `site-${ob.project.code}-${Math.random().toString(36).slice(2, 7)}` };
    st.S.projects.push(p);
    const tpl = st.S.stageTemplates.find((t) => t.isDefault); let cur = p.start; tpl.items.forEach((it, i) => { const pe = DO.addDays(cur, 60); st.S.stages.push({ id: st.nextId("st"), projectId: id, seq: i + 1, name: it.name, pct: it.pct, plannedStart: cur, plannedEnd: pe, actualStart: i < 4 ? cur : null, actualEnd: i < 3 ? pe : null, state: i < 3 ? "invoiced" : i === 3 ? "active" : "planned", requiredPurposes: i === 3 ? ["GFC"] : ["FA"], seniorQC: false, final: true, readySince: null, invoicedAt: i < 3 ? new Date().toISOString() : null, invoiceRef: null }); cur = DO.addDays(pe, 1); });
    const wdStage = st.stagesOf(id)[3];
    ob.sheets.forEach((n) => { const revs = ob.rows.filter((r) => r.number === n).sort((a, b) => (a.date > b.date ? 1 : -1)); const s = { id: st.nextId("s"), projectId: id, number: n, title: revs[0].title, discipline: revs[0].disc, stageId: wdStage.id, packageId: null, ownerId: "u_pl", checkerId: "u_dl", planned: revs[revs.length - 1].date, state: "issued", stateBefore: null, currentRevId: null, notes: "Onboarded", cadLink: "", aliases: [], reviewRound: 0, stateChangedAt: null, createdAt: new Date().toISOString(), replacedBy: null, cancelReason: "" }; st.S.sheets.push(s); revs.forEach((r, i) => { const rv = { id: st.nextId("r"), sheetId: s.id, code: r.rev, seq: i + 1, state: r.state, stageId: wdStage.id, purpose: r.purpose, suitability: "", fileName: r.file || `${n}_${r.rev}.pdf`, size: 2000000, uploadedBy: u.id, uploadedAt: `${r.date}T10:00:00+05:30`, issuedAt: `${r.date}T16:00:00+05:30`, issuedBy: "u_dc", transmittalId: null, supersededAt: r.state === "superseded" ? `${revs[i + 1].date}T16:00:00+05:30` : null, namingStatus: "ok", namingMessage: "", changeSummary: "", sha: String(DO.hash(n + r.rev)) }; st.S.revisions.push(rv); const pdf = ob.pdfs.find((f) => f.name === r.file); if (pdf) st.files.set(rv.id, pdf); if (r.state === "issued") s.currentRevId = rv.id; }); });
    st.audit("import", id, "onboarding", null, { sheets: ob.sheets.length, revisions: ob.rows.length }, { projectId: id, text: `${u.name} onboarded ${p.code} ${p.name}: ${ob.sheets.length} sheets, ${ob.rows.length} historic revisions (no notifications sent)` });
    ob.done = id; st.commit(); ui.toast({ title: `${p.code} loaded`, description: `${ob.sheets.length} sheets and ${ob.rows.length} revisions, silently.`, tone: "ok" });
  });
  DO.ONBOARD_CSV = "Project code,Project name,Client,Sheet number,Title,Discipline,Revision,Revision date,Purpose,File name\n2025-041,Sahakar Nagar Clinic,Sahakar Health Cooperative,A-101,Ground Floor Plan,A,P01,2025-11-04,FC,A-101_P01.pdf\n2025-041,Sahakar Nagar Clinic,Sahakar Health Cooperative,A-101,Ground Floor Plan,A,C01,2026-01-20,GFC,A-101_C01.pdf\n2025-041,Sahakar Nagar Clinic,Sahakar Health Cooperative,A-102,First Floor Plan,A,C01,2026-01-20,GFC,A-102_C01.pdf\n2025-041,Sahakar Nagar Clinic,Sahakar Health Cooperative,M-101,HVAC Layout - Ground Floor,M,C01,2026-02-03,GFC,M-101_C01.pdf\n2025-041,Sahakar Nagar Clinic,Sahakar Health Cooperative,E-101,Lighting Layout - Ground Floor,E,C01,2026-02-03,GFC,E-101_C01.pdf\n2025-041,Sahakar Nagar Clinic,Sahakar Health Cooperative,E-101,Lighting Layout - Ground Floor,E,C02,2026-03-12,GFC,E-101_C02.pdf\n";

  // ---------- F-39 Audit trail ----------
  function auditTrail(u, ctx) {
    const q = ctx.query;
    let rows = st.S.audit.map((a) => ({ at: a.at, actor: a.actorId, entity: a.entity, action: a.action, text: a.text, ip: a.ip, req: a.requestId, before: a.before, after: a.after }));
    st.S.transitions.slice(-1500).forEach((t) => { const s = st.sheet(t.sheetId); if (s && !st.S.audit.some((a) => a.at === t.at && a.entityId === s.id)) rows.push({ at: t.at, actor: t.userId, entity: "sheet", action: "state", text: `${st.userName(t.userId)} moved ${s.number} from ${st.label(t.from)} to ${st.label(t.to)}${t.reason ? ` · “${t.reason}”` : ""}`, ip: "10.20.4.11", req: `req-${t.id}`, before: { state: t.from }, after: { state: t.to } }); });
    if (q.entity) rows = rows.filter((r) => r.entity === q.entity); if (q.actor) rows = rows.filter((r) => r.actor === q.actor); if (q.q) { const t = q.q.toLowerCase(); rows = rows.filter((r) => r.text.toLowerCase().includes(t)); }
    rows.sort((a, b) => (a.at < b.at ? 1 : -1));
    ui.state.auditExport = rows; const page = +(q.p || 1); const size = 50;
    return html`${head("Audit trail", "Every state and field change: actor, time, entity, before and after, IP and request ID. Rows cannot be edited or deleted.", C.btn("Export (background job)", { icon: "download", act: "au-export" }))}
      <div class="filterbar"><div class="search-box">${icon("search", 14)}<input id="au-q" class="input" placeholder="Search the trail" value="${q.q || ""}" data-input="au-q" data-debounce="250" aria-label="Search the audit trail"></div>${C.select({ options: [["", "All entities"], ...[...new Set(rows.map((r) => r.entity).concat(st.S.audit.map((a) => a.entity)))].sort().map((e) => [e, e])], value: q.entity, change: "au-f", dataset: { k: "entity" }, aria: "Entity" })}${C.select({ options: [["", "Anyone"], ...st.S.users.map((x) => [x.id, x.name])], value: q.actor, change: "au-f", dataset: { k: "actor" }, aria: "Actor" })}<span class="small muted">${DO.fmtNum(rows.length)} rows</span></div>
      ${C.card({ body: html`<div class="t-wrap"><table class="t"><thead><tr><th>When</th><th>Actor</th><th>Entity</th><th>Change</th><th class="hide-md">Before → after</th><th class="hide-md">IP · request</th></tr></thead><tbody>${rows.slice((page - 1) * size, page * size).map((r) => html`<tr><td class="nowrap small">${DO.fmtDateTime(r.at)}</td><td class="small">${st.shortName(r.actor) === "—" ? "System" : st.shortName(r.actor)}</td><td><span class="pill">${r.entity}</span></td><td class="small">${r.text}</td><td class="hide-md small mono" style="white-space:normal">${r.before ? JSON.stringify(r.before).slice(0, 60) : "—"} → ${r.after ? JSON.stringify(r.after).slice(0, 60) : "—"}</td><td class="hide-md small muted">${r.ip}<br>${r.req}</td></tr>`)}</tbody></table></div>${C.pager(rows.length, page, size, "au-page")}` })}`;
  }
  ui.on("au-q", (el) => DO.app.setQuery({ q: el.value, p: "" }));
  ui.on("au-f", (el) => DO.app.setQuery({ [el.dataset.k]: el.value, p: "" }));
  ui.on("au-page", (el) => DO.app.setQuery({ p: el.dataset.p }));
  ui.on("au-page-size", () => {});
  ui.on("au-export", () => { const rows = ui.state.auditExport || []; DO.app.backgroundExport({ name: "audit-trail", title: "Audit trail export", columns: [{ label: "When", w: 1.3 }, { label: "Actor", w: 1.2 }, { label: "Entity" }, { label: "Change", w: 5 }, { label: "IP" }, { label: "Request" }], rows: rows.map((r) => [DO.fmtDateTime(r.at), st.userName(r.actor), r.entity, r.text, r.ip, r.req]) }, "csv"); });

  // ---------- S-13 Notification preferences ----------
  S.prefs = (ctx, u) => {
    const ev = st.EVENTS;
    return html`${C.pageHead({ title: "Notification preferences", meta: html`Instant notifications also go by email (to the demo mailbox). The daily digest arrives at ${st.S.org.digestTime} and lists only unread items.`, actions: C.btn("Send me today's digest now", { icon: "mail", act: "pf-digest" }) })}
      ${C.card({ body: html`<div class="t-wrap"><table class="t"><thead><tr><th>Event</th><th class="center">Instant</th><th class="center">Digest</th><th class="center">Off</th></tr></thead><tbody>${Object.entries(ev).map(([k, e]) => { const cur = st.prefOf(u, k); return html`<tr><td>${e.label}${e.mandatory ? html`<span class="small muted block">${icon("lock", 12)} Mandatory: you can't turn this off because work waits on you.</span>` : ""}</td>${["instant", "digest", "off"].map((m) => html`<td class="center"><input type="radio" name="pf-${k}" value="${m}" ${cur === m ? raw("checked") : ""} ${e.mandatory && m !== "instant" ? raw("disabled") : ""} data-change="pf-set" data-k="${k}" aria-label="${e.label}: ${m}"></td>`)}</tr>`; })}</tbody></table></div>` })}
      ${C.card({ title: "Quiet hours", cls: "mt-4", body: html`<form class="card-body flex wrap gap-3 items-end" data-submit="pf-quiet"><label class="field">From<input type="time" name="from" class="input sm" value="${u.prefs.quietFrom || "20:00"}"></label><label class="field">To<input type="time" name="to" class="input sm" value="${u.prefs.quietTo || "08:00"}"></label><button class="btn sm">Save quiet hours</button><span class="small muted">Instant emails wait until quiet hours end; in-app items still appear.</span></form>` })}`;
  };
  ui.on("pf-set", (el) => { const u = DO.auth.current(); u.prefs[el.dataset.k] = el.value; st.commit(); ui.toast({ title: `${st.EVENTS[el.dataset.k].label}: ${el.value}`, tone: "ok" }); });
  ui.on("pf-quiet", (f, d) => { const u = DO.auth.current(); u.prefs.quietFrom = d.from; u.prefs.quietTo = d.to; st.commit(); ui.toast({ title: "Quiet hours saved", tone: "ok" }); });
  ui.on("pf-digest", () => { const u = DO.auth.current(); const items = st.S.notifications.filter((n) => n.userId === u.id && !n.read); st.sendEmail({ to: [u.email], toName: u.name, subject: `Your DrawingOps digest · ${DO.fmtDate(DO.today())} · ${DO.plural(items.length, "unread item")}`, body: items.length ? items.slice(0, 15).map((n) => `• ${n.title}${n.body ? ` — ${n.body}` : ""}`).join("\n") : "Nothing unread. Nice.", link: "#/", kind: "digest" }); st.commit(); ui.toast({ title: "Digest sent to the demo mailbox", tone: "ok", action: { label: "Open", run: () => DO.app.go("/mailbox") } }); });

  S.profile = (ctx, u) => html`${C.pageHead({ title: "Profile", meta: `${u.email} · ${u.title}` })}<div class="grid g-2">${C.card({ title: "You", body: html`<dl class="kv card-body"><dt>Name</dt><dd>${u.name}</dd><dt>Email</dt><dd>${u.email}</dd><dt>Organisation role</dt><dd>${{ owner: "Owner / Principal", staff: "Staff", accounts: "Accounts", admin: "System admin" }[u.orgRole]}</dd><dt>Discipline</dt><dd>${st.disc(u.discipline)?.name || "—"}</dd><dt>Weekly capacity</dt><dd>${u.capacity} h</dd><dt>Sign-in</dt><dd>${u.mfa ? "Password + TOTP" : "Microsoft SSO"}</dd><dt>Projects</dt><dd>${st.S.projects.filter((p) => st.rolesOn(u, p).length).map((p) => html`<span class="block">${C.mono(p.code)} ${st.rolesOn(u, p).map((m) => st.ROLE_LABEL[m.role]).join(", ")}</span>`)}</dd></dl>` })}${C.card({ title: "Review delegation", body: html`<div class="card-body stack-2"><p>${u.delegate && u.delegate.until >= DO.today() ? `Your reviews go to ${st.userName(u.delegate.to)} until ${DO.fmtDate(u.delegate.until)}.` : "Not delegating."}</p>${C.btn("Set or change delegate", { act: "rq-delegate" })}<p class="small muted mt-3">Theme and row density are in the account menu (top right).</p></div>` })}</div>`;
})(window);
